pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed, uint256 msgValue, address actor) public {
        vm.assume(msgValue <= 10 ether);
        vm.assume(actor != address(0));

        bytes32 hash = bytes32(seed);
        vm.deal(actor, msgValue);
        vm.prank(actor);
        try c.lockInGuess{value: msgValue}(hash) returns (bool) {
            // Successful lockInGuess
            uint256 balAfter = address(c).balance;
            uint256 guessBlock = c.guesses(actor).block;
            // The invariant: if lockInGuess succeeds, guessBlock must be > 0 and balance must be exactly 1 ether more than the starting balance.
            assertTrue(guessBlock == 0 || (balAfter == 1 ether && msgValue == 1 ether));
        } catch {
            // If lockInGuess fails, the invariant is not violated; just pass.
            assertTrue(true);
        }
    }
}

