pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 hash, uint256 value) public {
        // Keep value in the admissible range: must not exceed the funding we can provide
        vm.assume(value <= 2 ether);
        // Fund a fresh caller with enough ether, including value for the call
        address caller = address(uint160(uint256(keccak256(abi.encodePacked(value)))));
        vm.deal(caller, value + 1 ether);
        // Record balance before
        uint256 balBefore = address(c).balance;
        // Perform lockInGuess
        vm.prank(caller);
        (bool ok, ) = address(c).call{value: value}(abi.encodeWithSignature("lockInGuess(bytes32)", hash));
        uint256 balAfter = address(c).balance;
        // Read the caller's guess block
        (uint256 guessBlock, ) = c.guesses(caller);
        // General rule: guessBlock > 0  <=>  balance increased by exactly 1 ether
        bool blockSet = guessBlock > 0;
        bool etherSentCorrect = (balAfter - balBefore) == 1 ether;
        assertTrue(blockSet == etherSentCorrect);
    }
}

