pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        // Provide ether to actor for lockInGuess
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(bytes32(uint256(1)));

        // Advance to the block after the guess block + 2 to ensure blockhash is available and settle is possible
        vm.roll(block.number + 2);

        uint256 balBefore = address(c).balance;
        vm.prank(actor);
        c.settle();
        uint256 balAfter = address(c).balance;

        // If settle succeeded (did not revert), and the guess matched (which we cannot read directly but can infer from balance change),
        // the balance must decrease by exactly 2 ether. If it decreased, it must be exactly 2 ether.
        bool settled = balBefore != balAfter;
        if (settled) {
            assertEq(balBefore - balAfter, 2 ether, "balance decrease must be exactly 2 ether");
        }
    }
}

