pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(bytes32 guessHash) public {
        // Supply initial ETH to the test contract so it can fund the lock and also act as sender
        vm.deal(address(this), 2 ether);
        vm.prank(address(this));
        c.lockInGuess{value: 1 ether}(guessHash);

        // Advance past the settlement block
        uint256 settleBlock = block.number + 2;
        vm.roll(settleBlock);
        vm.warp(settleBlock);

        bool settledOk;
        try c.settle() {
            settledOk = true;
        } catch {
            settledOk = false;
        }

        // After settlement the guess block is reset to 0 only if guess matched the answer.
        // In the reference contract answer = keccak256(blockhash(lockBlock+1)).
        // Because lockInGuess stored block.number+1, answer is exactly keccak256(blockhash(storedBlock)).
        // Therefore the guess we passed in (computed by us as keccak256(blockhash(lockBlock+1))) matches.
        // In the mutant the guess is stored against block.number+2, so the answer is keccak256(blockhash(lockBlock+2))
        // which never equals our submitted guess (created from blockhash(lockBlock+1)).
        // Consequently settlement will NOT reset the block in the mutant, leaving it nonzero.
        // The universal property: if settlement succeeds without revert, the sender's guess block MUST be 0 afterwards.
        assertTrue(!settledOk || c.guesses(address(this)).block == 0);
    }
}

