pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 hash, uint256 lockRoll, uint256 settleRoll) public {
        // Bound block numbers to reasonable future values to avoid past roll issues
        vm.assume(lockRoll < 1e8);
        vm.assume(settleRoll > lockRoll + 1 && settleRoll < 1e8);
        address actor = address(0x1234);
        vm.deal(actor, 2 ether);

        // Lock a guess at block lockRoll
        vm.roll(lockRoll);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash);

        // Move to settleRoll and attempt settlement
        vm.roll(settleRoll);
        vm.prank(actor);
        bool success;
        try c.settle() { success = true; } catch { success = false; }

        // After settlement, the contract must NOT have paid out 2 ether (either revert or no balance change)
        // In the reference, if the guess is correct and blockhash available, it would pay; but in the buggy
        // version, the stored block is lockRoll+2, which is guaranteed to be in the future (>= lockRoll+2).
        // Since settleRoll > lockRoll+1, lockRoll+2 might be past or future, but if settleRoll <= lockRoll+256
        // and hash matches blockhash(lockRoll+1), the reference could succeed. The bug always uses a future blockhash
        // that is zero, so no match.
        // Universal rule: if settlement succeeds, the contract balance must be exactly 1 ether (initial locked ether
        // still held because payout failed).
        assertTrue(!success || address(c).balance == 1 ether);
    }
}

