pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }
    function testFuzz_property(address caller, bytes32 hash) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));
        vm.deal(caller, 1 ether);
        vm.prank(caller);
        c.lockInGuess{value: 1 ether}(hash);
        // The guess mapping is private, but struct fields are stored.
        // We can read the stored bytes at the storage slot of guesses[caller].guess.
        // Slot of mapping guesses: 0
        // Slot of guesses[caller] is keccak256(abi.encode(caller, 0)).
        // Struct Guess has fields: uint block (slot 0), bytes32 guess (slot 1).
        // So guess is at keccak256(caller, 0) + 1.
        bytes32 storedGuess = vm.load(address(c), bytes32(uint256(keccak256(abi.encode(caller, uint256(0)))) + 1));
        assertEq(storedGuess, hash, "stored guess should equal the provided hash");
    }
}

