pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 hash) public {
        // Ensure the contract has enough ether to pay out 2 ether
        vm.deal(address(c), 2 ether);

        // Actor locks in a guess
        address actor = address(0x1234);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash);

        // Advance blocks so settle can be called
        vm.roll(block.number + 2);

        // Record balance before settle
        uint256 balanceBefore = actor.balance;
        vm.prank(actor);
        c.settle();
        uint256 balanceAfter = actor.balance;

        // The difference: if the guess equals the blockhash (hash == keccak256(abi.encodePacked(blockhash(lockBlock)))),
        // the reference contract pays 2 ether, while the buggy contract never pays because its stored guess is zero.
        // Therefore, the invariant is: if the actor receives exactly 2 ether, the hash must equal the expected answer.
        // We assert: !(balanceAfter == balanceBefore + 2 ether) || (hash == keccak256(abi.encodePacked(blockhash(block.number - 1))));
        bool gotPaid = (balanceAfter == balanceBefore + 2 ether);
        bool hashMatches = (hash == keccak256(abi.encodePacked(blockhash(block.number - 1))));
        assertTrue(!gotPaid || hashMatches);
    }
}

