import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        vm.deal(address(this), 2 ether);
        c = (new C){value: 1 ether}();
    }

    function testFuzz_property(bytes32 guessHash, uint8 blockOffset) public {
        // admissible domain: blockOffset > 0 so we can commit to a future block
        vm.assume(blockOffset > 0);

        // fund an account that will play the guesser
        address guesser = makeAddr("guesser");
        vm.deal(guesser, 2 ether);

        // commit a guess for a future block
        vm.prank(guesser);
        c.lockInGuess{value: 1 ether}(guessHash);

        // advance chain to the block after the committed block
        uint256 commitBlock = block.number; // block after lockInGuess, so commitBlock = guesses[guesser].block
        vm.roll(commitBlock + blockOffset); // ensure block.number > guesses[guesser].block

        // record balance before settle
        uint256 balanceBefore = guesser.balance;

        // settle
        vm.prank(guesser);
        c.settle();

        uint256 balanceAfter = guesser.balance;
        bool gotPaid = balanceAfter > balanceBefore;

        // The property: if the guesser got paid, then the guess hash must equal the blockhash of the committed block
        bytes32 expectedAnswer = keccak256(abi.encodePacked(blockhash(commitBlock)));
        assertTrue(!gotPaid || guessHash == expectedAnswer);
    }
}

