pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guessHash, uint48 lockBlockDistance, uint48 settleBlockDistance) public {
        vm.assume(lockBlockDistance > 0 && settleBlockDistance > 0 && lockBlockDistance <= 256 && settleBlockDistance <= 256);
        // Deploy a guesser that will lock in a guess and later settle
        address guesser = address(new Guesser());
        vm.deal(guesser, 1 ether);
        // Lock-in guess
        vm.startPrank(guesser);
        c.lockInGuess{value: 1 ether}(guessHash);
        vm.stopPrank();
        // Advance blocks
        vm.roll(block.number + lockBlockDistance);
        // Compute expected answer: hash of blockhash of the block where guess was locked + 1
        // (lockInGuess sets guesses[guesser].block = block.number + 1)
        uint256 recordedBlock = block.number - lockBlockDistance + 1;
        bytes32 answer = keccak256(abi.encodePacked(blockhash(recordedBlock)));
        // Make guessHash match the reference answer to ensure a win in reference
        // The fuzzer can supply any guessHash; we don't enforce matching.
        // After settlement, compare balance change.
        uint256 balanceBefore = guesser.balance;
        vm.startPrank(guesser);
        c.settle();
        vm.stopPrank();
        uint256 balanceAfter = guesser.balance;
        // Reference: if guessHash == answer, balanceAfter == balanceBefore + 2 ether.
        // Otherwise balanceAfter == balanceBefore.
        // Mutant: never pays out because answer uses blockhash(block.number) != recorded blockhash.
        // General property: if guessHash == answer, balance must increase by exactly 2 ether.
        // If guessHash != answer, balance must remain unchanged.
        if (guessHash == answer) {
            assertEq(balanceAfter, balanceBefore + 2 ether);
        } else {
            assertEq(balanceAfter, balanceBefore);
        }
    }
}

