pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        payable(address(c)).transfer(0); // avoid constructor value issue? constructor requires 1 ether payable, but we deploy with 0.
        // Actually constructor of C requires msg.value == 1 ether, so we need to deploy with value.
        // Override setUp to supply 1 ether.
        c = new C{value: 1 ether}();
    }
    function testFuzz_property(bytes32 hash, uint8 blockOffset) public {
        // blockOffset bounds the number of blocks to wait after lockInGuess before settling.
        vm.assume(blockOffset > 0 && blockOffset <= 255);

        // We'll use an arbitrary actor address. The fuzzer can vary msg.sender via prank.
        address actor = address(uint160(uint256(keccak256(abi.encode(hash, blockOffset)))));

        // Fund actor with 1 ether for lockInGuess
        vm.deal(actor, 1 ether);

        // Lock in guess
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash);

        // Advance blocks
        vm.roll(block.number + blockOffset);

        // Settle
        uint256 balBefore = address(actor).balance;
        vm.prank(actor);
        c.settle();
        uint256 balAfter = address(actor).balance;

        bytes32 answer = keccak256(abi.encodePacked(blockhash(c.guesses(actor)))); // guesses is public, auto-generated getter available
        // Unfortunately, after settle the block number is reset to 0, so the answer is lost.
        // We need to compute answer before settle or store it. We compute it before settle.
        // Reconstruct block number used: block.number after advance is original block + blockOffset, but lockInGuess sets block = block.number+1.
        // Let's recompute carefully inside the test after rolling to the correct block.
        // Actually we need to compute answer the same way the contract does. The contract uses blockhash(guesses[msg.sender].block).
        // guesses[msg.sender].block was set to block.number + 1 at the time of lockInGuess.
        // At the time of lockInGuess, block.number was some value B, then guesses.block = B + 1.
        // We advanced by blockOffset, so settle block.number = B + blockOffset.
        // The answer = keccak256(abi.encodePacked(blockhash(B + 1))).
        // We need to retrieve B. We can compute B by subtracting blockOffset and 1 from current block.number before settle.
        uint256 lockBlockNumber = block.number - blockOffset + 1;
        bytes32 answerComputed = keccak256(abi.encodePacked(blockhash(lockBlockNumber)));

        // The invariant: If the guess equals the answer, the actor MUST receive 2 ether in reference (and mutant may not).
        // If the guess does not equal answer, the actor MUST NOT receive any ether in reference, and may receive 2 ether in mutant.
        // So the invariant for reference: (guess == answer) ? (balAfter - balBefore == 2 ether) : (balAfter == balBefore).
        // Mutant violates this because it pays when guess != answer.
        bool invariant = (hash == answerComputed) ? (balAfter - balBefore == 2 ether) : (balAfter == balBefore);
        assertTrue(invariant);
    }
}

