import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guessHash, uint256 blockDelay) public {
        // Ensure the contract starts with exactly 1 ether from the constructor
        // The fuzzer needs a user that locks a guess
        address user = address(0x100);
        vm.deal(user, 1 ether);
        vm.prank(user);
        c.lockInGuess{value: 1 ether}(guessHash);

        // Advance blocks beyond the guess block
        // bound blockDelay to avoid overflow and keep within realistic limits
        blockDelay = bound(blockDelay, 1, 256);
        vm.roll(block.number + blockDelay);

        // Record the contract's balance before settling
        uint256 contractBalanceBefore = address(c).balance;

        // Attempt to settle
        vm.prank(user);
        c.settle();

        // The invariant: the total Ether in the system (contract balance + payouts to user)
        // should equal the total Ether deposited (1 ether from constructor + 1 ether from user = 2 ether).
        // The buggy version transfers only 1 ether instead of 2 ether on a correct guess,
        // leaving an extra 1 ether in the contract and breaking the balance conservation.
        uint256 contractBalanceAfter = address(c).balance;
        uint256 userBalanceAfter = user.balance;
        // If the guess was incorrect, settle does not transfer, so the sum remains 1 ether in contract + 1 ether with user = 2 ether.
        // If the guess was correct, the reference transfers 2 ether, sum becomes (contract 0 ether + user 3 ether) = 3 ether (but contract started with 1 and user paid 1, so total deposited is 2 + 1? Wait: constructor deposited 1, user deposited 1, total 2. Reference pays 2, so contract ends with 0, user ends with initial 0 + 2 = 2, sum = 2. Bug pays 1, contract ends with 1, user ends with 1, sum = 2? No, user started with 0, got 1, contract has 1, total 2. Incorrect guess: contract has 1, user has 0, sum = 1. That's not right either. Let's re-evaluate.
        // The user starts with 0 ether (we vm.deal them exactly 1 ether before lockInGuess). After lockInGuess, user has 0, contract has 2 (1 from constructor, 1 from user). Total system = 2.
        // If guess correct: reference -> user receives 2, contract 0, sum = 2. Bug -> user receives 1, contract 1, sum = 2. The sum is always 2 regardless.
        // The difference is not in total sum, but in distribution. So total balance conservation does not detect the bug.
        // Instead, we need a property that checks that a successful guess yields a net transfer of 2 ether to the user.
        // But we cannot directly read internal guess state to know if the guess was correct.
        // The bug is that on a correct guess, the user receives 1 ether less than they should. So we need to detect that difference.
        // We can observe the user's balance change. If the guess is correct, the reference gives 2 ether, the bug gives 1 ether.
        // Since the fuzzer picks the guess, we don't know if it was correct. So we need an invariant that holds for all guesses.
        // Consider: After settle, if the user's balance increased, the increase must be exactly 2 ether. Because in the reference, a correct guess always awards 2 ether. In the bug, a correct guess awards 1 ether, so the increase would be 1 ether, violating "if increase then exactly 2".
        // But what if the guess is incorrect? Then increase is 0. So the invariant: (balanceAfter - balanceBefore) is either 0 or 2 ether. That holds for reference (0 or 2). For bug, it can be 1 ether (when correct guess), so it violates the invariant.
        // Let's verify: user balance before settle = 0 (they spent all 1 ether on lockInGuess). Actually, lockInGuess costs 1 ether, so user.balance = 0 after lock. So after settle, user.balance is either 0 (incorrect) or 2 (correct reference) or 1 (correct bug). So the set of possible balances is {0,2} for reference, {0,1} for bug. So invariant: user.balance after settle is either 0 or 2 ether.
        // That's a perfect invariant! It holds for reference for all inputs, fails for bug for some input (when guess is correct).
        assertTrue(user.balance == 0 || user.balance == 2 ether);
    }
}

